    /**
     * The recurrence of a series.
     */
    func series(id: String, calendarId: String) async throws  -> CalendarSeries
    
    /**
     * Creates an event.
     */
    func create(draft: EventDraft, calendarId: String, notify: NotifyPolicy) async throws  -> CalendarEvent
    
    /**
     * Changes an event.
     */
    func update(reference: EventRef, patch: EventPatch, scope: RecurrenceScope, notify: NotifyPolicy) async throws  -> CalendarEvent
    
    /**
     * Deletes an event.
     */
    func delete(reference: EventRef, scope: RecurrenceScope, notify: NotifyPolicy) async throws 
    
    /**
     * Answers an invitation.
     */
    func respond(reference: EventRef, response: ResponseStatus, scope: RecurrenceScope, notify: NotifyPolicy) async throws  -> CalendarEvent
    
    /**
     * Gives the host the handler to call when the store changes. Called once, before the first read.
     */
    func setChangeHandler(handler: SystemChangeHandler) async 
    
}
