/**
 * The one error every throwing call of the bindings can throw (mirrors `Failure`, plus a rejected configuration).
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * A connector's own error.
     */
    case Source(SourceError
    )
    /**
     * The host cancelled, or the engine did.
     */
    case Cancelled
    /**
     * A write refused or failed.
     */
    case Write(WriteError
    )
    /**
     * A failure the host reported, as text.
     */
    case Host(
        /**
         * The host's description.
         */message: String
    )
    /**
     * The configuration or an argument the host passed is not acceptable.
     */
    case InvalidConfig(
        /**
         * What is wrong.
         */reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Source(
            try FfiConverterTypeSourceError.read(from: &buf)
            )
        case 2: return .Cancelled
        case 3: return .Write(
            try FfiConverterTypeWriteError.read(from: &buf)
            )
        case 4: return .Host(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .InvalidConfig(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Source(v1):
            writeInt(&buf, Int32(1))
            FfiConverterTypeSourceError.write(v1, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(2))
        
        
        case let .Write(v1):
            writeInt(&buf, Int32(3))
            FfiConverterTypeWriteError.write(v1, into: &buf)
            
        
        case let .Host(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidConfig(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


