enum HostError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The host could not reach the network.
     */
    case Network(
        /**
         * The host's description; may be empty.
         */message: String
    )
    /**
     * The user or the host cancelled.
     */
    case Cancelled
    /**
     * The thing asked for does not exist.
     */
    case NotFound
    /**
     * The host refused, for example for lack of permission.
     */
    case Denied
    /**
     * Any other failure.
     */
    case Failed(
        /**
         * The host's description; may be empty.
         */message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

